export type ParsedEarlyUnstakeInstruction<
  TProgram extends string = typeof SHORT_STAKE001_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    staker: TAccountMetas[0];
    payerWallet: TAccountMetas[1];
    tokenMint: TAccountMetas[2];
    stakerTokenAccount: TAccountMetas[3];
    marketVault: TAccountMetas[4];
    vaultTokenAccount: TAccountMetas[5];
    lenderOffer: TAccountMetas[6];
    tokenProgram: TAccountMetas[7];
  };
  data: EarlyUnstakeInstructionData;
};

export function parseEarlyUnstakeInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedEarlyUnstakeInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 8) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 8,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      staker: getNextAccount(),
      payerWallet: getNextAccount(),
      tokenMint: getNextAccount(),
      stakerTokenAccount: getNextAccount(),
      marketVault: getNextAccount(),
      vaultTokenAccount: getNextAccount(),
      lenderOffer: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getEarlyUnstakeInstructionDataDecoder().decode(instruction.data),
  };
}
